/* eslint-disable react-refresh/only-export-components -- Source packages export a definition, not a React refresh boundary. */
import {useEffect,useState} from 'react';
import {defineLocalTool,defineLocalToolBlock,LocalToolRichProseEditor,type LocalToolClient,type LocalToolJson,type LocalToolProps,type LocalToolSnapshot,type LocalToolStateAction} from '@/engines/local/sdk';
type Notes={notes:string};
type Evolving=Notes&{objectives?:{id:string;text:string}[];labels?:Record<string,string>;briefing?:string;priority?:string};
const initialState:Notes={notes:'Kept prose'};
const codec={version:1 as const,fields:{notes:{kind:'prose' as const}}};
const preview={version:1 as const,fields:[{key:'notes',label:{en:'Notes',es:'Notas'}}]};
const validateState=(value:LocalToolJson):value is Notes=>!!value&&typeof value==='object'&&!Array.isArray(value)&&typeof value.notes==='string';
const button='min-h-9 rounded-lg border border-border px-3 py-2 text-sm text-text-primary disabled:opacity-50';
function useNotebook<T extends Notes>(client:LocalToolClient<T>){
 const [snapshot,setSnapshot]=useState<LocalToolSnapshot<T>>(),[error,setError]=useState(''),[busy,setBusy]=useState(false),[undo,setUndo]=useState<string[]>([]),[redo,setRedo]=useState<string[]>([]);
 useEffect(()=>{let live=true;const reload=()=>void client.read().then(row=>{if(live)setSnapshot(row);}).catch(()=>{if(live)setError('Could not open this notebook.');});reload();const off=client.subscribe?.(reload);return()=>{live=false;off?.();};},[client]);
 const apply=async(actions:LocalToolStateAction[])=>{if(!snapshot||!client.state||busy)return;setBusy(true);setError('');try{const result=await client.state.apply(snapshot,actions);setSnapshot(result.snapshot);if(result.receiptId){setUndo(ids=>[...ids,result.receiptId!]);setRedo([]);}}catch{setError('Could not save. Reload and try again.');}finally{setBusy(false);}};
 const reverse=async(mode:'undo'|'redo')=>{const ids=mode==='undo'?undo:redo,id=ids.at(-1);if(!id||!client.state||busy)return;setBusy(true);setError('');try{const result=await client.state[mode](id);setSnapshot(result.snapshot);if(mode==='undo'){setUndo(list=>list.slice(0,-1));if(result.receiptId)setRedo(list=>[...list,result.receiptId!]);}else{setRedo(list=>list.slice(0,-1));if(result.receiptId)setUndo(list=>[...list,result.receiptId!]);}}catch{setError('This change can no longer be undone.');}finally{setBusy(false);}};
 return{snapshot,error,busy,apply,reverse,undo,redo};
}
function Notebook({client}:LocalToolProps<Notes>){const state=useNotebook(client);return <section className="space-y-3 text-text-primary"><h4 className="font-display text-lg">Evolving notebook</h4><p>{state.snapshot?.data.notes??'Opening notebook...'}</p><div className="flex flex-wrap gap-2"><button className={button} disabled={!state.snapshot||state.busy} onClick={()=>state.snapshot&&void state.apply([{type:'set',field:'notes',value:state.snapshot.data.notes+' Updated.'}])}>Append a note</button><button className={button} disabled={!state.undo.length||state.busy} onClick={()=>void state.reverse('undo')}>Undo notebook change</button><button className={button} disabled={!state.redo.length||state.busy} onClick={()=>void state.reverse('redo')}>Redo notebook change</button></div>{state.error&&<p role="alert">{state.error}</p>}</section>;}
const ownedInitial:Evolving={notes:'Kept prose',objectives:[{id:'fresh-seed',text:'Only a new notebook starts with this objective.'}],labels:{fresh:'Only a new notebook starts with this label.'},briefing:'<p>Declared initial briefing.</p>',priority:'Routine'};
const ownedCodec={version:1 as const,fields:{...codec.fields,objectives:{kind:'list' as const,idKey:'id'},labels:{kind:'map' as const},briefing:{kind:'prose' as const,format:'rich' as const},priority:{kind:'scalar' as const}}};
const ownedPreview={version:1 as const,fields:[...preview.fields,{key:'briefing',label:{en:'Briefing',es:'Informe'}},{key:'priority',label:{en:'Priority',es:'Prioridad'}}]};
const validateOwned=(value:LocalToolJson):value is Evolving=>{if(!validateState(value))return false;const data=value as Evolving;return(data.objectives===undefined||Array.isArray(data.objectives)&&data.objectives.every(item=>!!item&&typeof item==='object'&&!Array.isArray(item)&&typeof item.id==='string'&&typeof item.text==='string'))&&(data.labels===undefined||!!data.labels&&typeof data.labels==='object'&&!Array.isArray(data.labels)&&Object.values(data.labels).every(label=>typeof label==='string'))&&(data.briefing===undefined||typeof data.briefing==='string')&&(data.priority===undefined||typeof data.priority==='string');};
function EvolvingNotebook({client,context}:LocalToolProps<Evolving>){
 const state=useNotebook(client),data=state.snapshot?.data;
 return <section className="space-y-3 text-text-primary"><h4 className="font-display text-lg">Evolving notebook</h4><p>{data?.notes??'Opening notebook...'}</p>{data&&<><p>Priority: {data.priority}</p>{Array.isArray(data.objectives)?<div><h5>Objectives</h5>{data.objectives.length?<ul className="list-disc pl-6">{data.objectives.map(item=><li key={item.id}>{item.text}</li>)}</ul>:<p>No objectives yet.</p>}</div>:<p role="alert">Objectives are not available in this saved block.</p>}{data.labels&&<p>Labels: {Object.values(data.labels).join(', ')||'None yet.'}</p>}</>}
  <div className="flex flex-wrap gap-2"><button className={button} disabled={!data||state.busy} onClick={()=>data&&void state.apply([{type:'set',field:'notes',value:data.notes+' Updated.'}])}>Append a note</button><button className={button} disabled={!data||state.busy} onClick={()=>void state.apply([{type:'list-insert',field:'objectives',item:{id:crypto.randomUUID(),text:'Authored objective'},afterId:null}])}>Add objective</button><button className={button} disabled={!data||state.busy} onClick={()=>void state.apply([{type:'map-set',field:'labels',key:'authored',value:'Authored label'}])}>Add label</button><button className={button} disabled={!state.undo.length||state.busy} onClick={()=>void state.reverse('undo')}>Undo notebook change</button><button className={button} disabled={!state.redo.length||state.busy} onClick={()=>void state.reverse('redo')}>Redo notebook change</button></div>
  <LocalToolRichProseEditor client={client} context={context} field="briefing" label="Briefing"/>{state.error&&<p role="alert">{state.error}</p>}
 </section>;
}
// Existing Owned blocks opt into additions; fresh list/map items remain creation seeds.
const ownedOptions={key:'notebook',scope:'host' as const,name:{en:'Evolving notebook',es:'Cuaderno evolutivo'},codecEvolution:'additive' as const,initialState:ownedInitial,codec:ownedCodec,preview:ownedPreview,validateState:validateOwned,component:EvolvingNotebook};
const owned=defineLocalToolBlock(ownedOptions);
export default defineLocalTool({namespace:'examples.evolving-owned',name:{en:'Evolving notebook',es:'Cuaderno evolutivo'},description:{en:'A versioned local Owned notebook; source notes retain their existing contract.',es:'Cuaderno local versionado; las notas fuente conservan su contrato actual.'},document:{defaultTitle:{en:'Notebook',es:'Cuaderno'},embed:'interactive'},initialState,codec,preview,validateState,component:Notebook,blocks:[owned]});
